#!/usr/bin/env bash

set -ex

export PGHOST=$(minikube ip)
export PGUSER=postgres
export PGPORT=5432
export PGDATABASE=molecule_analysis
export PGPASSWORD=postgres
export DB_USER=chemist
export DB_USER_PASSWORD=$DB_USER

function delete_db() {
    dropdb --echo $PGDATABASE
}

function create_new_db() {
    # Run as Superuser
    createdb --echo --encoding='utf-8'
}

function delete_db_user() {
    # Run as Superuser
    psql -c "DROP ROLE $DB_USER;"
}

function create_db_user() {
    # Run as Superuser
    psql <<EOF
    CREATE USER $DB_USER WITH
    NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS
    CONNECTION LIMIT 256
    PASSWORD '$DB_USER';

    GRANT CONNECT, CREATE ON DATABASE $PGDATABASE TO $DB_USER;
EOF
}

function create_molecule_analysis_schema() {
    # Run as App User
    PGPASSWORD=$DB_USER_PASSWORD psql -U $DB_USER <<EOF
    CREATE SCHEMA IF NOT EXISTS molecule_analysis;

    GRANT ALL PRIVILEGES ON SCHEMA molecule_analysis TO $DB_USER;
    ALTER SCHEMA molecule_analysis OWNER TO $DB_USER;
EOF
}

function create_tables() {
    # Run as App User
    PGPASSWORD=$DB_USER_PASSWORD psql -U $DB_USER --file=data/schema.sql
}

function map_columns() {
    source_file=$1
    target_file=$2
    new_header=$3

    # Check if source file exists
    if [ ! -f "$source_file" ]; then
        echo "Error: $source_file is not found."
        exit 1
    fi

    # Write new header to target file
    echo "$new_header" > "$target_file"

    # Append source file content excluding its original first line
    tail -n +2 "$source_file" >> "$target_file"
}

